use vstd::prelude::*;

verus! {

fn reverse(s: Vec<i8>) -> (rev: Vec<i8>)
    ensures
        rev@ == s@.rev(),
        rev@.len() == s@.len(),
{
    let n = s.len();
    let mut rev: Vec<i8> = Vec::with_capacity(n);

    for i in 0..n
        invariant
            n == s.len(),
            rev@.len() == i as nat,
            // the prefix built so far matches the reverse of the corresponding suffix of `s`
            forall|k: int| 0 <= k < i ==> rev@[k] == s@[n as int - 1 - k],
        decreases n - i,
    {
        rev.push(s[n - 1 - i]);
    }

    // Connect the loop invariant to the postcondition
    assert(rev@.len() == n as nat);
    assert(forall|k: int| 0 <= k < n as int ==> rev@[k] == s@[n as int - 1 - k]);
    assert(rev@ == s@.rev());

    rev
}

} // verus!

